INSERT INTO `customer_specimen_result` VALUES('1505','HRM/20/0126','17','189','text_form','','','<table style=\"height: 740px;\" width=\"438\">\n<tbody>\n<tr>\n<td style=\"width: 423.219px;\">\n<p><span style=\"font-size: 18pt;\"><strong><span style=\"text-decoration: underline;\">Wound</span></strong></span><span style=\"font-size: 18pt;\">&nbsp;&nbsp;</span></p>\n</td>\n</tr>\n<tr>\n<td style=\"width: 423.219px;\">\n<p><span style=\"font-size: 18pt;\"><strong>Microscopy: Gram stainning</strong></span></p>\n<p><span style=\"font-size: 18pt;\">&middot;&nbsp; &nbsp; &nbsp; Numerous pus cells seen</span></p>\n<p><span style=\"font-size: 18pt;\">&middot;&nbsp; &nbsp; &nbsp; Few epithelial cells seen</span></p>\n<p><span style=\"font-size: 18pt;\">&middot;&nbsp; &nbsp; &nbsp; Gram positive cocci seen</span></p>\n</td>\n</tr>\n<tr>\n<td style=\"width: 423.219px;\">\n<p><span style=\"font-size: 18pt;\"><strong>Culture:</strong> Yielded moderate growth of <em>Staphylococcus aureus</em></span></p>\n</td>\n</tr>\n<tr>\n<td style=\"width: 423.219px;\">\n<p><span style=\"font-size: 18pt;\">Ciprofloxacin &ndash; Sensitive&nbsp; &nbsp; &nbsp; &nbsp;Augmentin&nbsp; &ndash; Sensitive</span></p>\n<p><span style=\"font-size: 18pt;\">Ceftriaxone - Resistant&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cotrimoxazole - Resistant</span></p>\n<p><span style=\"font-size: 18pt;\">Gentamicin &ndash; Resistant&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Cefuroxime &ndash; Resistant</span></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>','created','active','3571','2020-05-02','','12:38:13','3571','2020-05-04','15:46:21');
INSERT INTO `customer_specimen_result` VALUES('1506','HRM/20/0135','81','238','text_form','','','<p><span style=\"text-decoration: underline;\"><span style=\"font-size: 18pt;\">High Vaginal Swab (HVS) Microscopy Culture and Sensitivity</span></span></p>\n<p><span style=\"font-size: 18pt;\">Appearance: Whitish discharge on swab stick</span></p>\n<p><span style=\"text-decoration: underline;\"><span style=\"font-size: 18pt;\">Microscopy:</span></span></p>\n<ul>\n<li><span style=\"font-size: 18pt;\">Wet Preparation:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Pus cells: Numerous/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: 10-17/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Red blood cells: Nil</span></li>\n<li><span style=\"font-size: 18pt;\">Yeast: Nil</span></li>\n<li><span style=\"font-size: 18pt;\">Trichomonas: Nil</span></li>\n</ul>\n</li>\n<li><span style=\"font-size: 18pt;\">Gram smear:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Epithelial cells seen</span></li>\n<li><span style=\"font-size: 18pt;\">Numerous pus cells</span></li>\n<li><span style=\"font-size: 18pt;\">Gram negative intracellular diplococci: Not seen</span></li>\n<li><span style=\"font-size: 18pt;\">Gram negative bacilli and coccobacilli seen</span></li>\n</ul>\n</li>\n</ul>\n<p><span style=\"text-decoration: underline;\"><span style=\"font-size: 18pt;\">Culture:&nbsp;</span></span></p>\n<p><span style=\"font-size: 18pt;\">Yeilded no genital pathogen after&nbsp; 48 hours of aerobic incubation</span></p>\n<p><span style=\"font-size: 14pt;\">Comment: significant pus cells. possibilities include prior use of antibiotics, atypical bacterial infection-Chlamydia, Mycoplasma etc</span></p>','created','active','3571','2020-05-02','','12:48:52','3571','2020-05-04','16:51:03');
