INSERT INTO `customer_specimen_result` VALUES('2613','HRM/20/0196','17','189','text_form','','','<table style=\"height: 461px;\">\n<tbody>\n<tr style=\"height: 91px;\">\n<td style=\"height: 91px; width: 402.219px;\">\n<p><span style=\"text-decoration: underline; font-size: 18pt;\"><strong>WOUND SWAB M/C/S</strong></span></p>\n<ul>\n<li><span style=\"font-size: 18pt;\"><strong>Appearance: </strong>&nbsp;Brownish discharge on swab stick</span></li>\n</ul>\n</td>\n</tr>\n<tr style=\"height: 188px;\">\n<td style=\"height: 188px; width: 402.219px;\">\n<ul>\n<li><span style=\"font-size: 18pt;\"><strong>Microscopy:</strong> </span></li>\n<li><span style=\"font-size: 18pt;\"><strong>Gram Stain</strong></span></li>\n</ul>\n<p><span style=\"font-size: 18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;&nbsp; &nbsp; &nbsp; Pus cell seen</span></p>\n<p><span style=\"font-size: 18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;&nbsp; &nbsp; &nbsp; Epithelial cell seen</span></p>\n<p><span style=\"font-size: 18pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &middot;&nbsp; &nbsp; &nbsp; &nbsp;Few gram positive cocci seen</span></p>\n</td>\n</tr>\n<tr style=\"height: 53px;\">\n<td style=\"height: 53px; width: 402.219px;\">\n<p><span style=\"font-size: 18pt;\"><strong>Culture:</strong> Yielded no growth after 48 hours of aerobic incubation.</span></p>\n</td>\n</tr>\n<tr style=\"height: 129px;\">\n<td style=\"height: 129px; width: 402.219px;\"><span style=\"font-size: 14pt;\"><strong>Comment</strong>: Significant pus cell with no growth. Possibilities include: prior use of antibiotics, atypical or anaerobic bacterial etc.</span></td>\n</tr>\n</tbody>\n</table>\n<p>&nbsp;</p>','created','active','Bolaji','2020-05-07','','14:55:42','Bolaji','2020-05-08','18:15:35');
