INSERT INTO `customer_specimen_result` VALUES('3645','HRM/20/0312','81','238','text_form','','','<p><span style=\"text-decoration: underline;\"><span style=\"font-size: 18pt;\">High Vaginal Swab (HVS) Microscopy Culture and Sensitivity</span></span></p>\n<p><span style=\"font-size: 18pt;\">Appearance:</span></p>\n<p><strong><span style=\"font-size: 18pt;\">Microscopy:</span></strong></p>\n<ul>\n<li><span style=\"font-size: 18pt;\">Wet Preparation:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Pus cells: 2-5/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: 7-12/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Red blood cells: Nil</span></li>\n<li><span style=\"font-size: 18pt;\">Yeast: Nil</span></li>\n<li><span style=\"font-size: 18pt;\">Trichomonas: Nil</span></li>\n</ul>\n</li>\n<li><span style=\"font-size: 18pt;\">Gram smear:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: Seen</span></li>\n<li><span style=\"font-size: 18pt;\">Pus cells: Seen</span></li>\n<li><span style=\"font-size: 18pt;\">Gram negative intracellular diplococci: Not Seen</span></li>\n<li><span style=\"font-size: 18pt;\">Gram positive bacilli seen</span></li>\n</ul>\n</li>\n</ul>\n<p><span style=\"font-size: 18pt;\"><strong>Culture:</strong> Yeilded no growth after 48hours of aerobic incubation</span></p>\n<p>&nbsp;</p>','created','active','HRM/ST/005','2020-05-14','','13:05:40','3571','2020-05-15','12:22:23');
INSERT INTO `customer_specimen_result` VALUES('3646','HRM/20/0316','81','238','text_form','','','<p><span style=\"text-decoration: underline; font-size: 18pt;\">High Vaginal Swab (HVS) Microscopy Culture and Sensitivity</span></p>\n<p><span style=\"font-size: 18pt;\">Appearance: Whitish discharge on swab stick</span></p>\n<p><span style=\"text-decoration: underline;\"><span style=\"font-size: 18pt;\"><strong>Microscopy:</strong></span></span></p>\n<ul>\n<li><span style=\"font-size: 18pt;\">Wet Preparation:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Pus cells: 7-15/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: 10-25/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Red blood cells: Nil</span></li>\n<li><span style=\"font-size: 18pt;\">Yeast: Nil</span></li>\n<li><span style=\"font-size: 18pt;\">Trichomonas: Nil</span></li>\n</ul>\n</li>\n<li><span style=\"font-size: 18pt;\">Gram smear:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: Clue cell seen</span></li>\n<li><span style=\"font-size: 18pt;\">Pus cells: Seen</span></li>\n<li><span style=\"font-size: 18pt;\">Gram negative intracellular diplococci: Not seen</span></li>\n<li><span style=\"font-size: 18pt;\">Gram negative bacci &amp; coccobacilli seen</span></li>\n</ul>\n</li>\n</ul>\n<p><span style=\"font-size: 18pt;\"><span style=\"text-decoration: underline;\"><strong>Culture</strong>:</span> Yeilded no genital pathogen after 48 hours of incubation.</span></p>\n<p><span style=\"font-size: 14pt;\">Comment: Nugent score 8. Result is suggestive of bacterial vaginosis.</span></p>','created','active','HRM/ST/005','2020-05-14','','13:12:59','3571','2020-05-15','12:23:38');
