INSERT INTO `customer_specimen_result` VALUES('3815','HRM/20/0336','82','239','text_form','','','<p><span style=\"text-decoration: underline; font-size: 18pt;\">Endocervical Swab (ECS) Microscopy Culture&nbsp; &amp; Sensitivity</span></p>\n<p><span style=\"font-size: 18pt;\"><strong>Appearance</strong>: Whitish discharge on swab stick</span></p>\n<p><span style=\"font-size: 18pt;\"><strong>Microscopy:</strong></span></p>\n<ul>\n<li><span style=\"font-size: 18pt;\">Wet Preparation:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Pus cells: 2-4/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: 3-6/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">Red blood cells: 1-2/HPF</span></li>\n<li><span style=\"font-size: 18pt;\">others:&nbsp;</span></li>\n</ul>\n</li>\n<li><span style=\"font-size: 18pt;\">Gram smear:</span>\n<ul>\n<li><span style=\"font-size: 18pt;\">Epithelial cells: Seen</span></li>\n<li><span style=\"font-size: 18pt;\">Pus cells: Few seen</span></li>\n<li><span style=\"font-size: 18pt;\">Gram negative intracellular diplococci: Not seen</span></li>\n<li><span style=\"font-size: 18pt;\">others- Nil</span></li>\n</ul>\n</li>\n</ul>\n<p><span style=\"font-size: 18pt;\"><strong>Culture:</strong> Yielded no genital pathogen after 48 hours of aerobic incubation.</span></p>','created','active','3571','2020-05-15','','12:18:05','Bolaji','2020-05-16','14:10:32');
